# aeneid-073 (X.96-184): t is cut from the edition by A.cut; l, i, n drafted from the Latin.
import sys, os
HERE = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, HERE); sys.path.insert(0, os.path.join(HERE, '..', '..'))
import aeneid_lib as A

TITLE = 'Iovis nutus. Classis Etrusca'
PART = "Jupiter's Nod and the Etruscan Fleet (X.96–184)"
TITLE_EN = "Jupiter's Nod and the Etruscan Fleet — Aeneid X.96–184"
ABOUT = ("The council of the gods ends. The gods murmur, divided between Venus and Juno, and Jupiter gives his ruling: "
"since Trojans and Italians cannot be brought to peace, he will favour neither side; each will reap what he has begun, "
"and the fates will find their own way. He seals it with an oath by the Styx and a nod that shakes Olympus. On earth the "
"Rutulians press the siege of the Trojan camp, and the few defenders on the walls are named one by one, with young "
"Ascanius shining among them like a jewel set in gold. Meanwhile Aeneas is sailing back by night: Tarchon has joined "
"forces with him, and the Etruscans, freed by an oracle to follow a foreign leader, have taken to their ships, with "
"Pallas at Aeneas's side asking about the stars. Virgil calls on the Muses afresh and begins a catalogue of the "
"Etruscan captains and their ships, in the manner of Homer's Catalogue of Ships: Massicus in the Tiger, Abas, the "
"seer Asilas, and the handsome horseman Astur, with the towns that sent them. The catalogue continues in the next part.")

U = [
(99, 'ventos.',
 """With such words was Juno pleading, and all were murmuring,\nthe heaven-dwellers, with assent divided, as the first blasts,\nwhen caught in the woods, murmur and roll blind\nmurmurs, to sailors betraying the winds to come.""",
 """So Juno pleaded, and all the dwellers in heaven murmured, divided in their assent, as the first gusts of wind, caught among the trees, murmur and roll their hidden rumblings, warning sailors of the gale to come.""",
 """A new paragraph in Greenough. 'Talibus', 'with such (words)', 'dictis' understood, closing Juno's speech that ended the last part. 'orabat', imperfect, 'she was pleading'. 'adsensu vario', 'with divided assent', some for Venus, some for Juno; 'adsensu' is Greenough's spelling of 'assensu'. The simile is a weather-sign: wind trapped in a forest gives a low roar before a gale, as in Virgil's own Georgics (1.356–359). 'deprensa', 'caught', checked by the trees. 'caeca… murmura', 'blind murmurs', sounds with no visible source. 'fremebant… fremunt' echo each other: the gods' muttering is the wind's. 'ceu', 'as', one syllable. Elision 'caelicol(ae) adsensu'."""),
(101, 'infit;',
 """Then the father all-powerful, to whom over things is the first power,\nbegins;""",
 """Then the almighty father, who holds supreme power over all things, begins;""",
 """'pater omnipotens', Jupiter. 'rerum cui prima potestas', 'to whom (is) the first power over things', a dative of possession with 'est' left out (as 'sunt mihi' in Book I); 'rerum', objective genitive, the whole order of the world. 'infit', 'begins (to speak)', an old defective verb found in only a few forms, solemn and archaic. 'cui' is one syllable. No elisions."""),
(103, 'pontus:',
 """as he speaks, of the gods the lofty house falls silent,\nand trembling from its base the earth; silent is the steep aether;\nthen the Zephyrs lay down; presses its waters calm the sea:""",
 """as he speaks, the high house of the gods falls silent, and the earth trembles to its foundations; the heights of heaven are still, the west winds sink to rest, and the sea lays its waters smooth:""",
 """'eo dicente', ablative absolute, 'he speaking', 'as he speaks'; 'eo' two syllables. 'deum' = 'deorum', the old genitive plural. 'silescit', inceptive, 'grows silent'. 'tremefacta solo', 'made to tremble from its base', 'solo' ablative of 'solum', 'ground'; supply 'est'. 'arduus aether', 'the steep upper air'. 'posuere' = 'posuerunt', used without an object, 'lay down', 'were stilled'. 'premit… aequora', 'the sea presses its surface down', smooths it; 'placida' is proleptic, 'so that it is calm'. All nature hushed before the king of the gods speaks is an epic touch. Elision 'placid(a) aequora'."""),
(104, 'dicta.',
 """“Receive, then, in your minds, and these my words fix there.""",
 """“Take these words of mine to heart, then, and fix them there.""",
 """Jupiter's speech begins. 'Accipite… animis', 'receive in your minds', 'animis' a local ablative. 'ergo', 'then', 'so', marking a decision after the debate. 'figite', 'fix', 'drive in', as a nail is driven: let them stay. 'haec mea… dicta', 'these words of mine', framing the verb. Elisions 'Accipit(e) ergo', 'erg(o) animis', 'atqu(e) haec'."""),
(106, 'finem:',
 """Since the Ausonians to be joined in treaty with the Teucrians\nit is not allowed, nor does your discord admit an end:""",
 """Since the Ausonians may not be joined to the Trojans by treaty, and your discord admits of no ending:""",
 """'Quandoquidem', 'since indeed', a strong causal conjunction. 'Ausonios coniungi', accusative and infinitive with 'haud licitum (est)', 'it has not been permitted that the Ausonians be joined', 'licitum' impersonal, 'est' left out. 'Ausonios', the Italians, from Ausonia, an old poetic name for Italy. 'foedere', 'by treaty', ablative of means; 'Teucris', dative after 'coniungi'. 'capit', 'admits', 'has room for'. Jupiter's call for peace at the start of the council has failed, and he says so. 'coniungi' has a consonantal i. Elision 'Quandoquid(em) Ausonios'."""),
(108, 'habebo.',
 """what to each is his fortune today, what hope each cuts,\nTrojan or Rutulian he be, with no distinction I shall hold.""",
 """whatever fortune each man meets today, whatever hope each carves his way towards, be he Trojan or Rutulian, I shall hold him with no distinction.""",
 """'quae cuique est fortuna… quam quisque secat spem', two relative clauses with the antecedent folded in, 'whatever fortune each has, whatever hope each pursues'. 'secat spem', 'cuts a hope', a bold phrase: follows a hope's path, as a ship cuts the sea. 'Tros Rutulusne', 'Trojan or Rutulian', '-ne' here 'or'. 'fuat', an archaic present subjunctive of 'sum' = 'sit', solemn in a god's mouth. 'nullo discrimine habebo', 'I will hold (him) with no distinction', impartially. Elisions 'cuiqu(e) est', 'fortun(a) hodie', 'discrimin(e) habebo'."""),
(110, 'sinistris.',
 """Whether by the fates of the Italians the camp in siege is held,\nor by the evil error of Troy and warnings ill-starred.""",
 """It is all one whether the camp is held under siege by the fates of the Italians, or by Troy's own sad mistake and warnings misread.""",
 """'Seu… sive', 'whether… or', with the main thought supplied from what precedes: it makes no difference to Jupiter which is to blame. 'fatis Italum', 'by the fates of the Italians', 'Italum' = 'Italorum', the old genitive plural; destiny favouring Italy. 'castra… tenentur', 'the camp is held', the Trojan camp under siege since Book IX. 'errore malo Troiae', 'by Troy's evil mistake', and 'monitis sinistris', 'by ill-starred warnings', oracles misread or bad advice followed. Jupiter will not judge whose fault the war is. Elisions 'castr(a) obsidione', 'siv(e) errore'."""),
(111, 'solvo:',
 """Nor do I set free the Rutulians:""",
 """Nor do I release the Rutulians:""",
 """'Nec Rutulos solvo', 'nor do I set the Rutulians free': they too are bound by the same rule, and will get no special favour from the consequences of their acts. 'solvo', 'loose', 'release', a word for discharging someone from an obligation. A short clause, opened up by the colon to the explanation that follows. No elisions."""),
(112, 'ferent.',
 """his own beginnings to each the toil\nand the fortune will bring.""",
 """each man's own undertakings will bring him his hardship and his fortune.""",
 """'sua cuique exorsa', 'to each his own beginnings', the regular pairing of 'suus' with 'quisque', 'each his own'. 'exorsa', neuter plural of the participle of 'exordior', used as a noun, 'things begun', 'undertakings'. 'laborem fortunamque ferent', 'will bring toil and fortune', good or bad according to what each has started. The verb, held back over the line end, closes the thought sharply. Elision 'cuiqu(e) exorsa'."""),
(112, 'idem.',
 """King Jupiter to all the same.""",
 """King Jupiter is the same to all.""",
 """'Rex Iuppiter omnibus idem', 'King Jupiter (is) the same to all', with 'est' left out: a terse maxim, Jupiter naming himself in the third person, as a ruler pronouncing a decree. 'omnibus', dative. The god's impartiality is the theme of the whole speech. No elisions."""),
(115, 'Olympum.',
 """The fates a way will find.” By the Stygian streams of his brother,\nby the banks seething with pitch and with black whirlpool,\nhe nodded, and all with his nod made tremble Olympus.""",
 """The fates will find a way.” By the streams of his Stygian brother, by the banks that seethe with pitch in a black whirlpool, he nodded his assent, and with that nod he made all Olympus tremble.""",
 """The print has 'invenient. ”Stygii', a misprint for 'invenient.” Stygii', corrected here; t keeps the print. 'Fata viam invenient', 'the fates will find the way', the last words of Jupiter's speech: destiny will work itself out without his favour. He swears by the Styx, the river of the underworld ruled by his brother Pluto ('Stygii… fratris'), the oath no god may break; 'pice torrentis', 'boiling with pitch', 'torrentis' accusative plural in '-is' with 'ripas'. 'adnuit', Greenough's spelling of 'annuit', 'nodded': Homer's Zeus nods and great Olympus shakes (Iliad 1.528–530). These words repeat IX.104–106, Jupiter's oath to Cybele. Elision 'vi(am) invenient'."""),
(116, 'fandi.',
 """Here the end of speaking.""",
 """There his speaking ended.""",
 """'Hic finis fandi', 'here (was) the end of speaking', with 'erat' left out; 'fandi', genitive of the gerund of 'for, fari', 'to speak', a poetic verb. A half-line formula closing the scene; 'hic' may be 'here' or 'at this point'. No elisions."""),
(117, 'ducunt.',
 """From his throne then Jupiter golden\nrises, and the heaven-dwellers, him in their midst, to the threshold escort.""",
 """Then Jupiter rises from his golden throne, and the dwellers in heaven escort him in their midst to the threshold.""",
 """'Solio… aureo', 'from the golden throne', ablative of separation with 'surgit', framing the line; 'aureo' is read as two syllables, 'eo' run together (synizesis). 'quem', relative, 'whom', with 'Iuppiter' its antecedent. 'medium', 'in their midst', the place of honour. 'ad limina', 'to the threshold' of the hall, an escort out, as for a king leaving his council. The council of the gods, which opened Book X, is over. Elision 'qu(em) ad'."""),
(119, 'flammis.',
 """Meanwhile the Rutulians at the gates around, all of them, press on\nto lay low with slaughter the men and the walls to ring with flames.""",
 """Meanwhile the Rutulians press the attack at every gate around the camp, to cut the men down and ring the walls with fire.""",
 """A new paragraph in Greenough. The story returns to earth and to the siege of the Trojan camp where Book IX left it. 'portis… omnibus', 'at all the gates', local ablative, with 'circum' as an adverb, 'round about'. 'instant', 'press on', with the infinitives 'sternere' and 'cingere' expressing their aim, a poetic construction (prose would use 'ut'). 'caede', 'with slaughter'. 'moenia', the rampart of the camp. Elision 'circ(um) omnibus'."""),
(121, 'fugae.',
 """But the legion of the Aeneadae within its ramparts besieged is held,\nnor any hope of flight.""",
 """But the force of Aeneas's men is held pinned within its ramparts, and there is no hope of escape.""",
 """'legio', 'the legion', a Roman word given to the Trojan force. 'Aeneadum' = 'Aeneadarum', 'of the sons of Aeneas', his followers, with the old genitive plural in '-um'. 'vallis', 'by the palisades', 'within the ramparts'. 'obsessa tenetur', 'is held besieged'. 'nec spes ulla fugae', 'nor (is there) any hope of flight', 'est' left out. Elision 'legi(o) Aeneadum'."""),
(125, 'acies;',
 """Wretched, they stand on the towers high\nin vain, and with a thin crown the walls have ringed,\nAsius son of Imbrasus, and son of Hicetaon Thymoetes,\nand the two Assaraci, and with Castor old Thymbris,\nthe front line;""",
 """Pitiably, uselessly, they stand on the high towers and man the walls in a thin ring: Asius son of Imbrasus, Thymoetes son of Hicetaon, the two Assaraci, and old Thymbris with Castor, the front rank;""",
 """'Miseri… nequiquam', 'wretched… in vain', the poet's pity, the adverb thrown over the line end. 'rara… corona', 'with a thin crown', a ring of defenders spread too thin, a regular military sense of 'corona'. 'cinxere' = 'cinxerunt'. The names follow in a Homeric list: 'Imbrasides', 'son of Imbrasus', and 'Hicetaonius', 'son of Hicetaon', Greek patronymics; in the Iliad Hicetaon is a Trojan elder, brother of Priam. 'Assaraci duo', two men named after Assaracus, an ancestor of Aeneas. 'senior', 'the elder', Thymbris. 'prima acies', 'the front line', in apposition to them all. Elisions 'nequiqu(am) et', 'du(o) et', 'prim(a) acies'."""),
(126, 'alta.',
 """these the brothers of Sarpedon, both,\nboth Clarus and Thaemon, from Lycia accompany lofty.""",
 """with them stand the two brothers of Sarpedon, Clarus and Thaemon, come from the highlands of Lycia.""",
 """'hos… comitantur', 'these (men) they accompany', standing beside those just named. 'germani Sarpedonis ambo', 'both brothers of Sarpedon', the Lycian king, son of Jupiter, killed by Patroclus in the Iliad (Book 16). 'et Clarus et Thaemon', 'both Clarus and Thaemon'. 'Lycia… ab alta', 'from lofty Lycia', in south-west Asia Minor, Troy's ally; adjective and noun frame the verb. No elisions."""),
(129, 'Menestheo.',
 """Carries a huge, with his whole body straining, rock,\nno small part of a mountain, Lyrnesian Acmon,\nneither than Clytius his father less nor than his brother Menestheus.""",
 """Acmon of Lyrnesus, straining with his whole body, carries a huge rock, no small piece of a mountain, a man no less than his father Clytius or his brother Menestheus.""",
 """'Fert… saxum', 'carries a rock', the verb first and the subject held back to the end of the next line: the reader waits, as if under the weight. 'conixus', 'straining', perfect participle of 'conitor' (also spelt 'connixus'). 'haud partem exiguam montis', 'no small part of a mountain', litotes, in apposition to 'saxum'; Homer's heroes too lift stones that two men of later days could not carry (Iliad 5.302–304). 'Lyrnesius', 'of Lyrnesus', a town near Troy. 'nec… minor', 'not less', with ablatives of comparison 'Clytio genitore' and 'fratre Menestheo'. 'Menestheo' is read 'Me-nes-theo', the last two vowels run together. Elision 'part(em) exiguam'."""),
(131, 'sagittas.',
 """These with javelins, those strive to defend with stones,\nand to hurl fire, and on the string to fit arrows.""",
 """Some fight to hold the wall with javelins, others with stones; they hurl fire and fit arrows to the string.""",
 """'Hi… illi', 'these… those', 'some… others'. 'certant defendere', 'strive to defend', the infinitive with a verb of striving, poetic; so also 'moliri' and 'aptare'. 'iaculis… saxis', ablatives of means. 'moliri ignem', 'to launch fire', firebrands thrown down on the attackers; 'molior' suggests effort. 'nervo', 'to the string', 'nervus' the bowstring, dative with 'aptare'. 'Hi iaculis': the 'i' of 'iaculis' is a consonant, so there is no hiatus. Elisions 'moliriqu(e) ignem', 'nervoqu(e) aptare'."""),
(135, 'capiti;',
 """He himself in their midst, of Venus the most rightful care,\nthe Dardan boy, look, his head uncovered, his handsome head,\nlike a gem that gleams, which parts the tawny gold,\neither for neck an ornament or for head;""",
 """In the midst of them, see, is the Dardan boy himself, Venus's most rightful care, his handsome head uncovered, gleaming like a jewel set in tawny gold to adorn a neck or a head;""",
 """'Ipse', Ascanius, 'the Dardan boy', grandson of Venus through Aeneas, and so 'Veneris iustissima cura', 'most rightful object of Venus's care'. 'caput… detectus honestum', 'uncovered as to his handsome head', a passive participle with an accusative of the part affected, a Greek construction common in Virgil. 'ecce', 'look!', the poet pointing. The simile: 'qualis gemma micat', 'as a jewel gleams', 'quae dividit', 'which parts' the gold it is set in; 'collo… capiti', datives, for a necklace or a diadem. Elision 'Ips(e) inter'."""),
(137, 'ebur;',
 """or as, by art\nenclosed in boxwood or Orician terebinth,\nshines ivory;""",
 """or as ivory shines when a craftsman's skill has set it in boxwood or in terebinth from Oricum;""",
 """A second comparison, 'vel quale', 'or such as'. 'inclusum', 'enclosed', 'inlaid', ivory set into dark wood. 'buxo', 'boxwood', and 'terebintho', 'turpentine-tree', a Greek word with a Greek ending; both are dark, close-grained woods, so the white ivory shows bright against them, as the boy's white skin does among the armed men. 'Oricia', 'of Oricum', a port in Epirus, known for the terebinth. 'per artem', 'by art'. The line ends in a four-syllable Greek word, a Greek rhythm. Elision 'bux(o) aut'."""),
(138, 'auro.',
 """and his flowing locks his milk-white neck\nreceives, and, clasping them beneath, a circlet of pliant gold.""",
 """his hair flows loose over a neck as white as milk, caught up by a circlet of pliant gold.""",
 """'cui', 'whose', dative of reference ('to whom the neck…'), one syllable. 'fusos… crinis', 'the hair spread loose', 'crinis' accusative plural in '-is', framing the rest of the line. 'cervix… lactea', 'the milk-white neck', 'accipit', 'receives' the hair falling on it. 'subnectens circulus', 'a circlet binding beneath', a second subject of 'accipit' by a slight stretch: the neck takes both the hair and the band. 'molli… auro', 'of soft gold', pliant, beaten thin. No elisions."""),
(142, 'auro.',
 """You too saw the great-hearted, Ismarus, peoples\nwounds aiming and arming reeds with poison,\nof Maeonian house nobly born, where rich fields\nmen work, and Pactolus waters with gold.""",
 """You too, Ismarus, were seen by those great-hearted peoples aiming your wounding shafts and arming reeds with poison, you of noble birth from a Maeonian house, where men till rich fields and the Pactolus waters them with gold.""",
 """'Te quoque… Ismare', an apostrophe, the poet turning to address a warrior, a Homeric habit. 'magnanimae… gentes', 'great-hearted peoples', framing the line: both armies saw him. 'volnera dirigere', 'to aim wounds', arrows that wound; 'volnera' is Greenough's spelling of 'vulnera'. 'calamos', 'reeds', arrows; 'veneno', 'with poison'. 'Maeonia… domo', 'from a Maeonian house', ablative of origin with 'generose', vocative, 'nobly born'; Maeonia is Lydia, whose river Pactolus was said to carry gold dust. 'exercent', 'work', till. Elisions 'diriger(e) et', 'dom(o) ubi', 'Pactolusqu(e) inrigat'."""),
(145, 'Capys:',
 """Present too was Mnestheus, whom, of Turnus driven back, the recent\nfrom the rampart of the walls, on high the glory lifts,\nand Capys:""",
 """Mnestheus was there too, lifted high by the glory of having lately driven Turnus from the rampart of the walls, and Capys:""",
 """'Adfuit', 'was present', Greenough's spelling of 'affuit'. 'quem… sublimem… tollit', 'whom… lifts on high', 'sublimem' proleptic. 'pulsi… Turni… gloria', 'the glory of Turnus driven back', the participle doing the work of a verbal noun, 'the glory of driving Turnus back' (as in 'ab urbe condita', 'from the founding of the city'). Mnestheus led the rally that forced Turnus out of the camp at the end of Book IX. 'pristina', 'former', recent but already past. 'moerorum', Greenough's archaic spelling of 'murorum', 'of the walls'. 'Mnestheus', 'eu' one syllable. No elisions."""),
(145, 'urbi.',
 """from here a name to the Campanian is drawn city.""",
 """from him the Campanian city takes its name.""",
 """'hinc', 'from here', 'from him'. Virgil gives the old derivation of Capua, the chief city of Campania, from a Trojan Capys; 'Campanae… urbi', 'to the Campanian city', dative with 'ducitur', 'is derived'. Such founding-names, tying Italian places to Trojan heroes, run through the poem; a Capys was among Aeneas's captains in Book I (183). No elisions."""),
(147, 'contulerant:',
 """They among themselves of harsh war the contests\nhad joined:""",
 """So these men had been joining the hard contests of war among themselves:""",
 """A new paragraph in Greenough. 'Illi', 'they', both sides at the camp. 'certamina… contulerant', 'had brought together contests', 'conferre' the regular word for joining battle ('signa conferre', 'manum conferre'). The pluperfect sums up the fighting so far and clears the stage for Aeneas. 'duri… belli', genitive. Elision 'Ill(i) inter'."""),
(147, 'secabat.',
 """at midnight Aeneas the straits was cutting.""",
 """Aeneas, at midnight, was cutting through the sea.""",
 """'media… nocte', 'in the middle of the night', ablative of time, framing Aeneas and 'freta'. 'freta', 'straits', the sea. 'secabat', imperfect, 'was cutting', the keel slicing the water. With no 'but' to join them, the battle and the silent voyage stand side by side, the contrast all the sharper. Aeneas has been away from the camp since Book VIII. Elision 'medi(a) Aeneas'."""),
(150, 'ferat,',
 """For when, from Evander, into the Etruscan camp having entered,\nthe king he approaches, and to the king tells both his name and his race,\nand what he seeks, and what he himself brings,""",
 """For when, leaving Evander, he entered the Etruscan camp, went to the king, and told him his name and race, what he sought and what he himself had to offer,""",
 """A long period begins with 'Namque ut', 'for when', explaining how Aeneas came to be at sea. 'ab Euandro', 'from Evander', the Arcadian king at Pallanteum, the site of Rome, who sent him on to the Etruscans in Book VIII; 'Eu' is one syllable. 'regem', Tarchon, the Etruscan leader. 'nomenque genusque', 'both name and race', the double '-que'. 'quidve petat quidve… ferat', indirect questions, 'what he was seeking, or what he was bringing', '-ve' 'or'. 'regi', dative. Elisions 'Namqu(e) ut', 'reg(em) adit', 'quidv(e) ipse'."""),
(153, 'preces:',
 """Mezentius what arms\nis winning to himself, and the violent heart of Turnus\nhe explains, what in human affairs is the trust\nhe warns, and mingles prayers:""",
 """explained what forces Mezentius was winning to his side and how violent was the heart of Turnus, reminded him how little trust can be put in human fortunes, and mingled prayers with all of it:""",
 """The sentence runs on through three more verbs, 'edocet', 'admonet', 'immiscet', historic presents. 'Mezentius arma quae sibi conciliet', an indirect question with its subject put first, 'what arms Mezentius is winning to himself'; Mezentius, the exiled tyrant of Caere, has joined Turnus (Book VIII). 'violenta… pectora Turni', 'the violent heart of Turnus', plural for singular, a second object of 'edocet'. 'humanis… quae sit fiducia rebus', 'what confidence there is in human affairs', how unstable fortune is. Elision 'Turn(i) edocet'."""),
(154, 'ferit;',
 """no delay is made; Tarchon\njoins his strength and strikes a treaty;""",
 """there was no delay; Tarchon joins forces with him and strikes a treaty;""",
 """'haud fit mora', 'no delay is made', a brisk formula. 'Tarchon', the Etruscan king. 'iungit opes', 'joins his strength' to Aeneas's. 'foedus… ferit', 'strikes a treaty', the regular phrase, from the striking of the victim sacrificed to seal a pact. The short clauses mark the speed of it. No elisions."""),
(156, 'duci.',
 """then, free of fate,\nthe fleet boards, at the commands of the gods, the Lydian people,\nto a foreign leader entrusted.""",
 """then the Lydian people, freed from the bar of fate, board the fleet at the bidding of the gods, entrusted to a foreign leader.""",
 """'libera fati', 'free of fate', a genitive with an adjective of freedom, a Greek construction (prose has the ablative): an oracle had told the Etruscans that no Italian might lead them, and Aeneas, a foreigner, releases them from it (Book VIII). 'gens Lydia', 'the Lydian people', the Etruscans, believed to have come from Lydia in Asia Minor. 'iussis… divom', 'at the commands of the gods', 'divom' = 'divorum'. 'externo… duci', dative, 'to a foreign leader'. No elisions."""),
(158, 'Teucris.',
 """The Aeneian ship\nfirst place holds, at its beak having Phrygian yoked lions,\nabove looms Ida, to the exiled Teucrians most welcome.""",
 """Aeneas's ship holds the lead, Phrygian lions yoked beneath its beak, and above them towers Ida, a sight most welcome to the exiled Trojans.""",
 """'Aeneia puppis', 'Aeneas's ship', an adjective from his name; 'puppis', 'stern', stands for the whole vessel. 'prima tenet', 'holds the first place'. The figurehead shows the emblems of Cybele: 'Phrygios… leones', the lions that draw the Phrygian mother goddess's chariot, and 'Ida', her mountain above Troy, where Aeneas built his fleet. 'rostro… subiuncta leones', 'having lions yoked beneath at the beak', a passive participle taking an object, the Greek use seen at 133. 'profugis… Teucris', dative with 'gratissima'. Elision across the start of the unit, 'duc(i) Aeneia'."""),
(162, 'marique.',
 """Here great Aeneas sits and with himself turns over\nthe outcomes of war, various, and Pallas, to his left\nclose fastened side, now asks of the stars, of the dark\nnight the path, now what he has suffered by land and by sea.""",
 """Here great Aeneas sits, turning over in his mind the shifting chances of war, and Pallas, keeping close at his left side, asks him now about the stars, their guide on the dark night's journey, and now about all he has suffered on land and sea.""",
 """'Hic', 'here', on that ship. 'secum volutat', 'turns over with himself', ponders, a favourite Virgilian verb. 'eventus belli varios', 'the varied outcomes of war'. 'Pallas', Evander's young son, given to Aeneas to learn war under him (Book VIII). 'sinistro adfixus lateri', 'fastened to his left side', never leaving it. 'iam… iam', 'now… now'. 'sidera, opacae noctis iter', 'the stars, the path of the dark night', the stars ships steered by. 'quae passus', 'what he has suffered', 'sit' left out; 'terraque marique', 'both by land and sea'. Elision 'sider(a) opacae'."""),
(165, 'vehatur.',
 """Throw open now Helicon, goddesses, and set your songs moving,\nwhat band meanwhile from the Tuscan shores accompanies\nAeneas, and arms his ships, and over the sea is carried.""",
 """Now, goddesses, throw Helicon open and stir up your songs: tell what force came meanwhile from the Tuscan shores with Aeneas, armed his ships, and sailed with him over the sea.""",
 """A new paragraph in Greenough. A fresh invocation of the Muses before a catalogue, as in Iliad 2.484–493 before the Catalogue of Ships; the first line repeats the opening of Virgil's catalogue of the Italians (VII.641). 'Pandite… Helicona', 'open Helicon', the Muses' mountain in Boeotia, as if its springs of song lay behind doors; 'Helicona' is a Greek accusative. 'deae', vocative. 'quae manus… comitetur… armet… vehatur', indirect questions, depending on the idea of telling. 'Aenean', Greek accusative. No elisions."""),
(166, 'tigri:',
 """Massicus on the bronze-clad, foremost, cuts the waters, Tiger:""",
 """Massicus leads, cutting the waters in the bronze-beaked Tiger;""",
 """A new paragraph in Greenough. The catalogue of the Etruscan captains begins. 'aerata… tigri', 'on the bronze-clad Tiger', the ship's name, its beak sheathed in bronze; 'tigri' is ablative of 'tigris', and adjective and noun frame the line. 'princeps', 'first', first in the list and first in the line of ships. Ships named for their figureheads were usual, as in the boat-race of Book V. No elisions."""),
(169, 'arcus.',
 """under whom a thousand-strong band of youths, who the walls of Clusium\nand who the city left of Cosae, whose weapons are arrows\nand quivers light on their shoulders and the death-bearing bow.""",
 """Under him sail a thousand young men who had left the walls of Clusium and the city of Cosae, their weapons arrows, light quivers on their shoulders, and the bow that deals death.""",
 """'sub quo', 'under whom', under his command. 'mille manus iuvenum', 'a band of a thousand young men', with the verb left out. 'Clusi', 'of Clusium', an inland Etruscan city; 'Cosas', Cosae, on the coast. 'liquere' = 'liquerunt'. 'quis' = 'quibus', the old dative plural of the relative, a dative of possession: 'to whom (are) arrows as weapons'. 'goryti', 'quivers', a Greek word. 'letifer', 'death-bringing', a poetic compound. Elision 'quiqu(e) urbem'."""),
(170, 'Abas:',
 """Together grim Abas:""",
 """With him came grim Abas;""",
 """'Una', 'together', 'along with him', an adverb. 'torvus', 'grim', 'fierce-looking'. Abas is a Greek-sounding name; a Trojan Abas was named among the ships in the storm of Book I (121). Half a line, with the verb left out, as catalogues allow. No elisions."""),
(171, 'puppis.',
 """to him the whole, in conspicuous arms,\ncolumn, and with a gilded Apollo gleamed his ship.""",
 """all his company shone in splendid armour, and his ship gleamed with a gilded Apollo.""",
 """'huic', dative of reference, 'his'. 'totum… agmen… fulgebat', 'his whole column shone', the verb shared by the two subjects, 'agmen' and 'puppis'. 'insignibus armis', 'with conspicuous arms', ablative. 'aurato… Apolline', 'with a gilded Apollo', the god's image as the ship's figurehead or sign. Elision 'tot(um) insignibus'."""),
(174, 'metallis.',
 """Six hundred to him had given Populonia his mother,\nexperienced in war, young men, but Ilva three hundred,\nthe island with inexhaustible, of the Chalybes, rich metals.""",
 """Populonia, his mother city, had given him six hundred young men tried in war, and the isle of Elba three hundred, rich in inexhaustible mines of Chalybean iron.""",
 """'Sescentos… trecentos', the numbers at the start and end. 'Populonia mater', 'mother Populonia', his native city, an Etruscan port facing Elba. 'expertos belli', 'experienced in war', a genitive with an adjective of knowledge. 'ast', an old poetic form of 'at', 'but'. 'Ilva', Elba, famous in antiquity for its iron. 'Chalybum', 'of the Chalybes', a people on the Black Sea proverbial as iron-workers, so 'Chalybum metallis', 'mines like the Chalybes'', mines of iron. 'generosa', 'rich', 'nobly endowed'. Elision 'insul(a) inexhaustis'."""),
(178, 'hastis.',
 """Third, that famous one, of men and gods the interpreter, Asilas,\nto whom the entrails of beasts, to whom the stars of heaven are obedient,\nand the tongues of birds, and of the foretelling lightning the fires,\na thousand hurries along, dense in rank and with bristling spears.""",
 """Third came Asilas, the famed interpreter between men and gods, whom the entrails of victims obey, and the stars of heaven, the voices of birds, and the fires of the prophetic thunderbolt; he hurries a thousand men along, close-ranked and bristling with spears.""",
 """'ille', 'that famous', marking a man of renown. 'hominum divomque interpres', 'interpreter of men and gods', the go-between who reads heaven's will; 'divom' = 'divorum'. Asilas commands the whole Etruscan art of divination, for which the Etruscans were famous at Rome: 'pecudum fibrae', the entrails of victims read by the haruspex; 'caeli… sidera'; 'linguae volucrum', the cries of birds; 'praesagi fulminis ignes', lightning read as an omen. 'parent', 'obey', answer him truly. 'rapit', 'hurries along'. 'acie', ablative of manner. Elisions 'ill(e) hominum', 'divomqu(e) interpres', 'volucr(um) et', 'aci(e) atque'."""),
(180, 'solo.',
 """These to obey bids, from Alphean origin, Pisa,\na city Etruscan in soil.""",
 """These men are bidden to obey him by Pisa, a city sprung from Pisa on the Alpheus, Etruscan only in its soil.""",
 """'Hos parere iubent… Pisae', 'Pisa bids these (men) obey', sends them to serve under Asilas; 'Pisae' is plural in form, so 'iubent' is plural. 'Alpheae ab origine', 'from an Alphean origin': Etruscan Pisa was said to have been founded from Pisa in Elis, on the river Alpheus near Olympia. 'urbs Etrusca solo', 'a city Etruscan in its soil', 'solo' an ablative of respect: Greek by descent, Etruscan by ground. Elision 'Alphe(ae) ab'."""),
(181, 'armis.',
 """Follows most handsome Astur,\nAstur, in his horse trusting and in his many-coloured arms.""",
 """Next comes Astur, most handsome of them all, Astur, who trusts in his horse and his armour of many colours.""",
 """'Sequitur', 'follows', 'comes next'. 'Astur… Astur', the name repeated across the line end, a Homeric touch that gives the man his moment of glory. The Latin Library prints the name 'Astyr'; Greenough's 'Astur' is the same man. 'equo fidens', 'trusting in his horse', 'fido' with the ablative. 'versicoloribus armis', 'with many-coloured arms', a long word filling the end of the line. No elisions."""),
(184, 'Graviscae.',
 """Three hundred add (one mind to all, of following)\nthose who have Caere for home, who are in the fields of Minio,\nand Pyrgi the ancient and unwholesome Graviscae.""",
 """Three hundred more are added, all of one mind to follow him: men whose home is Caere, men from the fields by the Minio, from ancient Pyrgi and from fever-ridden Graviscae.""",
 """'Tercentum adiciunt', 'add three hundred', the subjects being the men and towns that follow. '(mens omnibus una sequendi)', a parenthesis, 'all have one mind for following', 'omnibus' a dative of possession. 'qui Caerete domo', 'who (are) from Caere as home', 'domo' an ablative of origin, as often with towns; Caere was Mezentius's own city, which had driven him out. 'Minionis in arvis', 'in the fields of the Minio', a small river of southern Etruria. 'Pyrgi', the port of Caere, and 'Graviscae', both on the coast; 'intempestae', 'unwholesome', explained of old by its feverish air. 'adiciunt' has a long first syllable, as if 'adiiciunt'. Elision 'Tercent(um) adiciunt'. The catalogue continues in the next part."""),
]

P = A.part('aeneid-073'); L = A.lines_of(P); paras = {l['n'] for l in L if l['p']}
cuts = A.cut(P, [(u[0], u[1]) for u in U])
sents = []; prev_end_line = None
for (t, ln), (_, _t, l, i, n) in zip(cuts, U):
    u = {'t': t, 'l': l, 'i': i, 'n': n}
    if prev_end_line != ln and ln in paras: u['p'] = True
    u['v'] = True; u['ln'] = ln; sents.append(u)
    prev_end_line = ln + t.count('\n')
    if t.count('\n') != l.count('\n'): print('LINE COUNT', ln, repr(t[:30]), t.count('\n'), l.count('\n'))
    if t.count('\n') > 4: print('TOO LONG', ln)
    if '\n' in i: print('NEWLINE IN i', ln)
    if t.rstrip('”]')[-1] not in A.TERMINAL + ',': print('ENDING', ln, repr(t[-12:]))
    nw = len(n.split())
    if nw > 139 or nw < 15: print('NOTE LENGTH', ln, nw)
    for mk in '“”[]':
        if t.count(mk) != l.count(mk): print('MARK l', ln, mk)
        if mk in '“”' and t.count(mk) != i.count(mk): print('MARK i', ln, mk)
A.jdump({'title': TITLE, 'titleEn': TITLE_EN, 'part': PART, 'about': ABOUT, 'sentences': sents}, os.path.join(HERE, 'units.json'))
print(len(sents), 'units')
